window.CODE = Object.assign(window.CODE || {}, {"ch38/agent_files.py":"\"\"\"Which instruction files does this repository have, and which coding tool reads which?\n\nEvery AI coding tool wants a plain-text file that tells it how YOUR project works. They\ndisagree on the file name. This script lists what a repository has and shows, per tool,\nwhat that tool would pick up. It reads nothing but file names and the first lines.\n\n    python agent_files.py            # look at the current folder\n    python agent_files.py ../ch39/starter   # or any repository\n\nThe table TOOL_READS records what the vendors' own pages said on 5 November 2026.\nVendors change this often, so treat it as a dated snapshot, not a law of nature.\n\"\"\"\nfrom __future__ import annotations\n\nimport re\nimport sys\nfrom dataclasses import dataclass\nfrom pathlib import Path\n\n# tool -> list of (glob pattern relative to the repo root, what it is)\n# Sources (all read 5 Nov 2026): code.claude.com/docs/en/memory, agents.md,\n# docs.github.com Copilot \"custom instructions support\", cursor.com/docs/rules.\nTOOL_READS: dict[str, list[tuple[str, str]]] = {\n    \"Claude Code\": [\n        (\"CLAUDE.md\", \"project instructions\"),\n        (\".claude/CLAUDE.md\", \"project instructions\"),\n        (\"CLAUDE.local.md\", \"your private notes (keep out of git)\"),\n        (\".claude/rules/*.md\", \"rules, optionally limited to some paths\"),\n        (\"AGENTS.md\", \"read only when there is no CLAUDE.md (see claude_reads)\"),\n    ],\n    \"GitHub Copilot\": [\n        (\".github/copilot-instructions.md\", \"repository-wide instructions\"),\n        (\".github/instructions/**/*.instructions.md\", \"path-specific instructions\"),\n        (\"AGENTS.md\", \"agent instructions (support differs by surface)\"),\n        (\"CLAUDE.md\", \"agent instructions (support differs by surface)\"),\n        (\"GEMINI.md\", \"agent instructions (support differs by surface)\"),\n    ],\n    \"Cursor\": [\n        (\".cursor/rules/*.mdc\", \"project rules\"),\n        (\"AGENTS.md\", \"plain-markdown alternative to rules\"),\n    ],\n    \"Other tools that follow the AGENTS.md convention\": [\n        (\"AGENTS.md\", \"an open, plain-markdown 'README for agents'\"),\n    ],\n}\n\nIMPORT_RE = re.compile(r\"^\\s*@(\\S+)\", re.M)\n\n\n@dataclass\nclass Found:\n    path: str\n    lines: int\n\n\ndef find_files(root: str | Path) -> list[Found]:\n    root = Path(root)\n    seen: dict[str, Found] = {}\n    for patterns in TOOL_READS.values():\n        for pattern, _ in patterns:\n            for p in sorted(root.glob(pattern)):\n                if p.is_file():\n                    rel = p.relative_to(root).as_posix()\n                    seen.setdefault(rel, Found(rel, len(p.read_text(errors=\"replace\").splitlines())))\n    return sorted(seen.values(), key=lambda f: f.path)\n\n\ndef imports(path: Path) -> list[str]:\n    \"\"\"The @path lines in a CLAUDE.md-style file (an import pulls another file in).\"\"\"\n    return IMPORT_RE.findall(path.read_text(errors=\"replace\")) if path.is_file() else []\n\n\ndef claude_reads(root: str | Path) -> list[str]:\n    \"\"\"Apply the rule from Claude Code's memory page (read 5 Nov 2026):\n    AGENTS.md is read only when no CLAUDE.md / .claude/CLAUDE.md / CLAUDE.local.md exists;\n    a CLAUDE.md that imports @AGENTS.md includes it. Simplified to one folder: the real\n    rule also looks in the folders above the one you start Claude in.\"\"\"\n    root = Path(root)\n    claude = [n for n in (\"CLAUDE.md\", \".claude/CLAUDE.md\", \"CLAUDE.local.md\") if (root / n).is_file()]\n    out = list(claude)\n    if not claude and (root / \"AGENTS.md\").is_file():\n        out.append(\"AGENTS.md\")\n    for n in claude:\n        for imp in imports(root / n):\n            if (root / imp).is_file() and imp not in out:\n                out.append(imp)\n    out += [p.relative_to(root).as_posix() for p in sorted(root.glob(\".claude/rules/*.md\"))]\n    return out\n\n\ndef warnings(root: str | Path) -> list[str]:\n    root = Path(root)\n    out = []\n    have = {f.path for f in find_files(root)}\n    if \"CLAUDE.md\" in have and \"AGENTS.md\" in have and \"AGENTS.md\" not in imports(root / \"CLAUDE.md\"):\n        out.append(\"Both CLAUDE.md and AGENTS.md exist and CLAUDE.md does not import AGENTS.md: \"\n                   \"two sources of truth that will drift. Put the shared rules in AGENTS.md and \"\n                   \"start CLAUDE.md with the line @AGENTS.md.\")\n    for f in find_files(root):\n        if f.lines > 200:\n            out.append(f\"{f.path} has {f.lines} lines; Claude Code's guide recommends staying under 200.\")\n    if not have:\n        out.append(\"No instruction file found. The agent will have to guess your commands and conventions.\")\n    return out\n\n\ndef report(root: str | Path) -> str:\n    root = Path(root)\n    found = find_files(root)\n    lines = [f\"Instruction files in {root.resolve()}:\"]\n    lines += [f\"  {f.path}  ({f.lines} lines)\" for f in found] or [\"  (none)\"]\n    have = {f.path for f in found}\n    lines.append(\"\")\n    for tool, patterns in TOOL_READS.items():\n        hits = sorted({p for p in have for pat, _ in patterns if Path(p).match(pat) or p == pat})\n        lines.append(f\"{tool}: \" + (\", \".join(hits) if hits else \"nothing it knows about\"))\n    lines.append(\"\")\n    lines.append(\"Claude Code would load: \" + (\", \".join(claude_reads(root)) or \"nothing\"))\n    for w in warnings(root):\n        lines.append(\"WARNING: \" + w)\n    return \"\\n\".join(lines)\n\n\nif __name__ == \"__main__\":\n    print(report(sys.argv[1] if len(sys.argv) > 1 else \".\"))\n","ch38/README.md":"# Chapter 38 · AI coding tools landscape\n\n`agent_files.py` lists the instruction files a repository has (CLAUDE.md, AGENTS.md, Copilot and Cursor files)\nand shows which tool reads which. The table of file names is a snapshot of the vendors' pages on 5 Nov 2026.\n\n    python agent_files.py ../ch39/starter\n    python -m pytest -q          # 8 tests, no network\n","ch38/test_ch38.py":"import agent_files as af\n\n\ndef make(tmp_path, files):\n    for name, text in files.items():\n        p = tmp_path / name\n        p.parent.mkdir(parents=True, exist_ok=True)\n        p.write_text(text)\n    return tmp_path\n\n\ndef test_empty_repo_warns(tmp_path):\n    assert af.find_files(tmp_path) == []\n    assert \"No instruction file\" in af.warnings(tmp_path)[0]\n\n\ndef test_agents_md_only_is_read_by_claude(tmp_path):\n    make(tmp_path, {\"AGENTS.md\": \"# Commands\\n- pytest\\n\"})\n    assert af.claude_reads(tmp_path) == [\"AGENTS.md\"]\n\n\ndef test_claude_md_wins_over_agents_md(tmp_path):\n    make(tmp_path, {\"AGENTS.md\": \"a\\n\", \"CLAUDE.md\": \"b\\n\"})\n    assert af.claude_reads(tmp_path) == [\"CLAUDE.md\"]\n    assert any(\"two sources of truth\" in w for w in af.warnings(tmp_path))\n\n\ndef test_import_pulls_agents_md_in_and_silences_warning(tmp_path):\n    make(tmp_path, {\"AGENTS.md\": \"a\\n\", \"CLAUDE.md\": \"@AGENTS.md\\n\\n# Claude only\\n\"})\n    assert af.claude_reads(tmp_path) == [\"CLAUDE.md\", \"AGENTS.md\"]\n    assert af.warnings(tmp_path) == []\n\n\ndef test_rules_directory_always_counts(tmp_path):\n    make(tmp_path, {\"AGENTS.md\": \"a\\n\", \".claude/rules/api.md\": \"x\\n\"})\n    assert af.claude_reads(tmp_path) == [\"AGENTS.md\", \".claude/rules/api.md\"]\n\n\ndef test_long_file_is_flagged(tmp_path):\n    make(tmp_path, {\"CLAUDE.md\": \"line\\n\" * 250})\n    assert any(\"250 lines\" in w for w in af.warnings(tmp_path))\n\n\ndef test_matrix_for_every_tool(tmp_path):\n    make(tmp_path, {\"AGENTS.md\": \"a\\n\", \".github/copilot-instructions.md\": \"c\\n\",\n                    \".cursor/rules/style.mdc\": \"---\\nalwaysApply: true\\n---\\nx\\n\",\n                    \".github/instructions/py/tests.instructions.md\": \"t\\n\"})\n    text = af.report(tmp_path)\n    assert \"GitHub Copilot: .github/copilot-instructions.md, .github/instructions/py/tests.instructions.md, AGENTS.md\" in text\n    assert \"Cursor: .cursor/rules/style.mdc, AGENTS.md\" in text\n    assert \"Claude Code: AGENTS.md\" in text\n    assert \"Claude Code would load: AGENTS.md\" in text\n\n\ndef test_cli_runs_on_current_folder(tmp_path, capsys, monkeypatch):\n    make(tmp_path, {\"CLAUDE.md\": \"x\\n\"})\n    monkeypatch.chdir(tmp_path)\n    print(af.report(\".\"))\n    assert \"CLAUDE.md  (1 lines)\" in capsys.readouterr().out\n","common/requirements.txt":"# Pinned versions the course code was tested with. Install with: pip install -r requirements.txt\nopenai==3.43.0\nanthropic==2.4.0\npython-dotenv>=1.0\npydantic==2.13.5\ntiktoken>=0.8            # Chapter 2\nfastapi==0.162.0         # Chapter 5\nuvicorn>=0.30\npython-multipart>=0.0.9\nhttpx>=0.27\nstreamlit==1.66.1\ngradio==6.31.0\npytest>=8\n\n# Part C: frameworks and protocols (tested versions)\nlangchain==1.4.8                 # Chapters 12-13\nlangchain-core==1.7.4\nlangchain-openai==1.7.3\nlangchain-anthropic==1.7.9\nlangchain-community==0.4.2\nlangchain-text-splitters==1.1.3\nlangchain-classic==1.0.8         # only for legacy examples (AgentExecutor, old retrievers)\nlanggraph==1.2.19                # Chapters 14-15\nlanggraph-checkpoint-sqlite==3.1.3\nmcp==1.30.0                      # Chapters 16-17\nlangchain-mcp-adapters==0.3.2\nnetworkx==3.7                    # Chapter 18 (GraphRAG)\nchromadb==1.5.9                  # Chapters 6, 18, 19\nagno==3.1.12                     # Chapter 19\n# Optional: langchain-tavily, wikipedia, langchain-experimental (Chapter 13 built-in tools)\n# DSPy (Chapter 20) goes in a separate environment: see ch20/requirements-dspy.txt\n\n# Part D: multi-agent\n# CrewAI (Chapter 24) and AutoGen (Chapter 25) need their own environments: ch24/requirements-crewai.txt, ch25/requirements-autogen.txt\na2a-sdk==1.3.0                   # Chapter 26 (agent interoperability)\nfastapi==0.162.0\nuvicorn==0.54.0\n"});
